package org.shadowice.flocke.andotp.View;

import android.content.Context;
import android.text.method.TransformationMethod;
import android.util.AttributeSet;

import androidx.annotation.Nullable;

import com.google.android.material.textfield.TextInputEditText;

/**
 * A {@link TextInputEditText} that notifies a listener whenever its
 * {@link TransformationMethod} is changed.
 *
 * This is needed because the password visibility toggle of the surrounding
 * {@link com.google.android.material.textfield.TextInputLayout} does not offer any way to be
 * notified about its state, it simply replaces the transformation method of the attached
 * {@link android.widget.EditText}. Observing those changes allows us to keep additional input
 * fields (e.g. a password confirmation field) in sync with the toggle.
 */
public class ObservableTextInputEditText extends TextInputEditText {
    public interface OnTransformationMethodChangedListener {
        void onTransformationMethodChanged(@Nullable TransformationMethod method);
    }

    @Nullable
    private OnTransformationMethodChangedListener transformationMethodChangedListener = null;

    public ObservableTextInputEditText(Context context) {
        super(context);
    }

    public ObservableTextInputEditText(Context context, AttributeSet attrs) {
        super(context, attrs);
    }

    public ObservableTextInputEditText(Context context, AttributeSet attrs, int defStyleAttr) {
        super(context, attrs, defStyleAttr);
    }

    public void setOnTransformationMethodChangedListener(@Nullable OnTransformationMethodChangedListener listener) {
        this.transformationMethodChangedListener = listener;
    }

    @Override
    public void setTransformationMethod(@Nullable TransformationMethod method) {
        super.setTransformationMethod(method);

        // This might be called from the constructor of the base class, before our own fields
        // have been initialized, so the listener needs to be null-checked.
        if (transformationMethodChangedListener != null)
            transformationMethodChangedListener.onTransformationMethodChanged(getTransformationMethod());
    }
}

