arguments.new_string:
    public static void hideKeyboard(Context context, View view) {
        if (view != null) {
            InputMethodManager imm = (InputMethodManager) context.getSystemService(Context.INPUT_METHOD_SERVICE);
            imm.hideSoftInputFromWindow(view.getWindowToken(), 0);
        }
    }

    /**
     * Keeps the visibility of the text of additional input fields (e.g. a password confirmation
     * field) in sync with the password input field, so that they all react to the
     * "show password" toggle of the surrounding
     * {@link com.google.android.material.textfield.TextInputLayout}.
     */
    public static void linkTextVisibility(ObservableTextInputEditText passwordInput, final EditText... linkedInputs) {
        applyTextVisibility(passwordInput.getTransformationMethod(), linkedInputs);

        passwordInput.setOnTransformationMethodChangedListener(new ObservableTextInputEditText.OnTransformationMethodChangedListener() {
            @Override
            public void onTransformationMethodChanged(TransformationMethod method) {
                applyTextVisibility(method, linkedInputs);
            }
        });
    }

    private static void applyTextVisibility(TransformationMethod method, EditText... inputs) {
        for (EditText input : inputs) {
            if (input == null || input.getTransformationMethod() == method)
                continue;

            // Changing the transformation method can reset the position of the cursor,
            // so it has to be saved and restored manually.
            int selectionStart = input.getSelectionStart();
            int selectionEnd = input.getSelectionEnd();

            input.setTransformationMethod(method);

            if (selectionStart >= 0 && selectionEnd >= 0)
                input.setSelection(selectionStart, selectionEnd);
        }
    }
}

