arguments.new_string:
    /**
     * Keeps the text visibility of additional input fields (e.g. a password confirmation field) in
     * sync with the given password input field, so that all of them react to the "show password"
     * toggle of the surrounding
     * {@link com.google.android.material.textfield.TextInputLayout}.
     *
     * The password toggle does not provide a way to be notified about its state, it simply
     * replaces the {@link android.text.method.TransformationMethod} of the password input field.
     * Doing so causes the text of that field to be set again, which allows us to detect the change
     * with a simple {@link TextWatcher}.
     */
    public static void linkTextVisibility(final EditText passwordInput, final EditText... linkedInputs) {
        syncTextVisibility(passwordInput, linkedInputs);

        passwordInput.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {
                syncTextVisibility(passwordInput, linkedInputs);
            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {}

            @Override
            public void afterTextChanged(Editable s) {}
        });
    }

    private static void syncTextVisibility(EditText source, EditText... inputs) {
        boolean hidden = isTextHidden(source);

        for (EditText input : inputs) {
            if (input == null || isTextHidden(input) == hidden)
                continue;

            // Changing the transformation method resets the position of the cursor,
            // so it has to be saved and restored manually.
            int selectionStart = input.getSelectionStart();
            int selectionEnd = input.getSelectionEnd();

            input.setTransformationMethod(hidden ? PasswordTransformationMethod.getInstance() : null);

            if (selectionStart >= 0 && selectionEnd >= 0)
                input.setSelection(selectionStart, selectionEnd);
        }
    }

    private static boolean isTextHidden(EditText input) {
        return input.getTransformationMethod() instanceof PasswordTransformationMethod;
    }
}

